const state = $getWorkflowStaticData("global"),
  until = Date.now();
if (state.lastCompanyRun == null) state.lastCompanyRun = until;
if (
  !Number.isSafeInteger(state.lastCompanyRun) ||
  state.lastCompanyRun < 0 ||
  state.lastCompanyRun > until
)
  throw Error("Invalid company watermark");
return [
  {
    json: {
      since: state.lastCompanyRun,
      until,
      zendeskBase: "https://YOUR_ZENDESK_SUBDOMAIN.zendesk.com",
    },
  },
];

const start = $("Read the last run time").first().json,
  rows = [];
for (const page of $input.all()) {
  if (!page.json.body || !Array.isArray(page.json.body.results))
    throw Error("Invalid HubSpot list");
  for (const c of page.json.body.results) {
    const t = Date.parse(c.updatedAt);
    if (!c || typeof c.id !== "string" || !c.properties || !Number.isFinite(t))
      throw Error("Invalid HubSpot company");
    if (t >= start.since && t < start.until) rows.push(c);
  }
}
return rows.length ? [{ json: { companies: rows } }] : [];

const companies = $("Select changed HubSpot companies").first().json.companies,
  orgs = [];
for (const page of $input.all()) {
  if (!Array.isArray(page.json.body?.organizations)) throw Error("Invalid Zendesk organizations");
  orgs.push(...page.json.body.organizations);
}
const byName = new Map(),
  seen = new Set();
for (const o of orgs) {
  if (!Number.isSafeInteger(o.id) || typeof o.name !== "string")
    throw Error("Invalid Zendesk organization");
  const k = o.name.toLowerCase();
  byName.set(k, [...(byName.get(k) || []), o]);
}
return companies.map((c) => {
  const name = c.properties?.name,
    domain = c.properties?.domain;
  if (typeof name !== "string" || !name.trim() || typeof domain !== "string" || !domain.trim())
    throw Error("Company name or domain missing");
  const k = name.toLowerCase();
  if (seen.has(k)) throw Error("Duplicate HubSpot company names");
  seen.add(k);
  const matches = byName.get(k) || [];
  if (matches.length > 1) throw Error("Duplicate Zendesk organization names");
  return { json: { id: matches[0]?.id ?? null, name, domain } };
});

if (!Number.isSafeInteger($json.organization?.id) || $json.organization.id < 1)
  throw Error("Zendesk did not confirm organization");
const expected = $("Process companies one by one").item.json.id;
if (expected !== null && $json.organization.id !== expected)
  throw Error("Zendesk confirmed a different organization");
return $input.all();

const until = $("Read the last run time").first().json.until;
if (!Number.isSafeInteger(until)) throw Error("Invalid run time");
$getWorkflowStaticData("global").lastCompanyRun = until;
return $input.all();
